import{_ as s,c as o,o as r,a3 as t,j as a}from"./chunks/framework.BT-mtt1U.js";const p=JSON.parse('{"title":"Admission","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Admissions.md","filePath":"wiki/Admissions.md","lastUpdated":null}'),i={name:"wiki/Admissions.md"};function n(l,e,c,d,h,u){return r(),o("div",null,e[0]||(e[0]=[t('<h1 id="admission" tabindex="-1">Admission <a class="header-anchor" href="#admission" aria-label="Permalink to &quot;Admission&quot;">​</a></h1><p><strong>Admissions are completely online at <a href="https://sdmis.nios.ac.in" target="_blank" rel="noreferrer">sdmis.nios.ac.in</a> only</strong> (for 12th (Sr. Sec), 10th (Sec), and OBE).</p><h1 id="secondary-10th-standard" tabindex="-1">Secondary (10th Standard) <a class="header-anchor" href="#secondary-10th-standard" aria-label="Permalink to &quot;Secondary (10th Standard)&quot;">​</a></h1><p>This course is equivalent to the Xth standard. However, NIOS integrates 9th and 10th into one grade. The content of 9th and 10th grades is present in its books. Unlike other boards, you may choose your subjects from the <a href="https://www.nios.ac.in/departmentsunits/academic/senior-secondary-course-equivalent-to-class-xii.aspx" target="_blank" rel="noreferrer">table</a>.<br><img src="https://cdn.jsdelivr.net/gh/nios-students/docs@master/wiki/assets/Screenshot%202024-09-13%20190823.png" alt="Screenshot" width="400"></p><p><strong>Exceptions</strong></p><ol><li><p>a) You are required to take <strong>at least 1 language subject</strong>.</p><p>b) You <strong>can take up to 2 language subjects</strong>, e.g., Hindi and English <em><strong>✔</strong></em> <s>Hindi, English, and Arabic</s> <em><strong>X</strong></em>.</p></li><li><p>a) You are required to opt for <strong>4 academic subjects for &quot;certification&quot;</strong> (<em>not</em> including language subjects).</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The reason why &quot;certification&quot; is in quotes is because part/dual students don&#39;t get a certificate. They just pass specific subjects that they need for their career.<br> e.g., For taking admission into a commercial pilot course, one of the requirements is that the student has to study Physics and Mathematics in 12th. So, they register in part admission to fulfill the requirements.<br><strong>IF</strong> you just passed 8th/9th (i.e., a fresher), you must click <strong>NO</strong> for part admission when registering/filling the admission form.</p></div><p>b) You can add 2 <strong>more subjects, but the maximum count of subjects shouldn&#39;t exceed seven (i.e., no more than 7 subjects)</strong>.</p><p>c) You can choose one vocational subject.</p><p>d) NIOS lets you choose any subject; however, you <strong>MUST</strong> choose your subjects according to your future career/goals.</p><p>e) Don&#39;t think that you can complete 12th in one year. <strong>If you passed out of 10th, you are required to maintain a 1-year gap between passing 10th and completing 12th.</strong></p></li></ol><h1 id="senior-secondary-12th-standard" tabindex="-1">Senior Secondary (12th Standard) <a class="header-anchor" href="#senior-secondary-12th-standard" aria-label="Permalink to &quot;Senior Secondary (12th Standard)&quot;">​</a></h1><p>This course is equivalent to the 12th standard. However, NIOS integrates 11th and 12th into one grade. The content of 11th and 12th grades is present in its books. Unlike other boards, you may choose your subjects from the <a href="https://www.nios.ac.in/departmentsunits/academic/senior-secondary-course-equivalent-to-class-xii.aspx" target="_blank" rel="noreferrer">table</a>.<br><img src="https://cdn.jsdelivr.net/gh/nios-students/docs@master/wiki/assets/Screenshot%202024-09-13%20190823.png" alt="Screenshot" width="400"></p><p><strong>Exceptions</strong></p><ol><li><p>a) You are required to take <strong>at least 1 language subject</strong>.</p><p>b) You <strong>can take up to 2 language subjects</strong>, e.g., Hindi and English <em><strong>✔</strong></em> <s>Hindi, English, and Arabic</s> <em><strong>X</strong></em>.</p></li><li><p>a) You are required to opt for <strong>4 academic subjects for &quot;certification&quot;</strong> (<em>not</em> including language subjects).</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The reason why &quot;certification&quot; is in quotes is because part/dual students don&#39;t get a certificate. They just pass specific subjects that they need for their career.<br> e.g., For taking admission into a commercial pilot course, one of the requirements is that the student has to study Physics and Mathematics in 12th. So, they register in part admission to fulfill the requirements.<br><strong>IF</strong> you just passed 8th/9th (i.e., a fresher), you must click <strong>NO</strong> for part admission when registering/filling the admission form.</p></div><p>b) You can add 2 <strong>more subjects, but the maximum count of subjects shouldn&#39;t exceed seven (i.e., no more than 7 subjects)</strong>.</p><p>c) NIOS lets you choose any subject; however, you <strong>MUST</strong> choose your subjects according to your future career/goals.</p><p>d) Don&#39;t think that you can complete 12th in one year. <strong>If you passed out of 10th, you are required to maintain a 1-year gap between passing 10th and completing 12th.</strong></p><p>e) You can choose one <a href="https://nios-students.pages.dev/wiki/FAQ&#39;S#what-is-the-two-vocational-subjects-role:~:text=12th%20Vocational%20Subjects" target="_blank" rel="noreferrer">vocational subject</a>.</p></li></ol><p>Procedure: NIOS has introduced <strong>100% online</strong> admission to facilitate learners in registering themselves. Offline admission quotas have been dispensed with. Under this scheme, learners have the options to:</p><ul><li>Register themselves online directly.</li><li>Visit their Regional Centres/Study Centres for online registration. (<em>They aren&#39;t helpful mostly.</em>)</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>We suggest that you register yourself for admission through the <a href="https://sdmis.nios.ac.in" target="_blank" rel="noreferrer">NIOS SDMIS website</a>; it&#39;s easy!</p></div><p><a href="https://youtube.com/playlist?list=PLSh652xpu_YH8C93k-3hMEH5yCnIwSAyQ&amp;si=ii9xb-BGTGF8NkX4" target="_blank" rel="noreferrer">Link to more detailed information on Admissions</a> | <a href="https://drive.google.com/drive/folders/1S8z_RbST1EgllO27tPGU_uemNi7Kdpsj" target="_blank" rel="noreferrer">Official Guidelines</a></p><h1 id="streams-of-admission" tabindex="-1">Streams of Admission <a class="header-anchor" href="#streams-of-admission" aria-label="Permalink to &quot;Streams of Admission&quot;">​</a></h1><p>In NIOS, there are <strong>primarily four streams</strong>. Unlike other boards, you can choose any subjects you like. The term &quot;stream&quot; in the context of NIOS isn&#39;t Science, Commerce, Humanities, and Arts; it’s based on factors such as whether you are taking Public Exams or On-Demand Exams.</p>',16),a("iframe",{width:"640",height:"360",src:"https://www.youtube.com/embed/NpNZ-BbiLag",title:"NIOS_Types_of_Admission",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""},null,-1),t('<h1 id="stream-1" tabindex="-1">Stream 1 <a class="header-anchor" href="#stream-1" aria-label="Permalink to &quot;Stream 1&quot;">​</a></h1><p>Open to all learners and freshers. Admissions are open throughout the year. Examinations are held in April-May for Block 1 learners and October-November for Block 2 learners. (<em>Although you may give exams in different blocks from yours and <a href="https://nios-students.pages.dev/wiki/Exams-Assignments#ode-on-demand-examination" target="_blank" rel="noreferrer">On Demand</a>, after the first exam is past, you don&#39;t have to appear in it.</em>) Students in Stream 1 must submit TMAs and attend PCP classes. <a href="./Exams-Assignments.html">More info on TMA &amp; PCP</a> | <a href="https://sdmis.nios.ac.in/home/fees#:~:text=Fee%20Structure%20%2D%20(With%20Late%20Fee)%20for%20Stream%201%20Block%20I" target="_blank" rel="noreferrer">Admission schedule Stream I</a> | <a href="https://dq4kzxd7fbbni.cloudfront.net/static/dist/images/pdf/process-flow/ProcessFlowDetailed_SecSrSec_Stream1and2_June2023.pdf" target="_blank" rel="noreferrer">Registration flow chart</a> | <a href="https://sdmis.nios.ac.in/home/fees#:~:text=Fee%20Structure%20%2D%20(Without%20Late%20Fee)%20for%20Stream%201%20of%20Online%20Admission" target="_blank" rel="noreferrer">Fee Structure</a></p><h1 id="stream-2" tabindex="-1">Stream 2 <a class="header-anchor" href="#stream-2" aria-label="Permalink to &quot;Stream 2&quot;">​</a></h1><p>This stream is available for learners who have failed or passed but want to improve scores in the Secondary or Senior Secondary (10th class or 12th class) examination from a recognized board and want to update their qualification in one or up to four subjects to meet eligibility criteria for their goals (e.g., admission into a commercial pilot course). These exams are conducted during October-November Public Examinations.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>For students enrolled in Stream 2, <strong>examination fees are included in the admission fees for the first time.</strong></p></div><h1 id="stream-3-and-4" tabindex="-1">Stream 3 and 4 <a class="header-anchor" href="#stream-3-and-4" aria-label="Permalink to &quot;Stream 3 and 4&quot;">​</a></h1><p>On-Demand Examination System (ODES) at Secondary Level (10th class) and Senior Secondary Level (12th class). Open for admissions throughout the year. Suitable for learners seeking to update their qualifications or clear failed subjects. <a href="https://rcguwahati.nios.ac.in/registration-for-on-demand-examination-ode-and-procedure.html" target="_blank" rel="noreferrer">More Info on Stream 3 &amp; 4</a></p><h1 id="transfer-of-credit-toc" tabindex="-1">Transfer of Credit (ToC) <a class="header-anchor" href="#transfer-of-credit-toc" aria-label="Permalink to &quot;Transfer of Credit (ToC)&quot;">​</a></h1><p>ToC is one of the flagship features of NIOS. <strong>Failed</strong> learners can transfer the marks of <strong>2</strong> subjects from the parent board to NIOS.</p><p><strong>Rules and Norms of ToC:</strong></p><ul><li>The ToC fee is ₹<strong>230 per subject</strong> (as per NEW notification: <a href="https://www.nios.ac.in/media/documents/notification/yr2024/Exam/Notification-34-2024.pdf" target="_blank" rel="noreferrer">37/2024</a>).</li><li>The subject you wish to transfer must be in NIOS&#39;s curriculum.</li><li>The <strong>original failed marksheet</strong> should be present in <strong>physical form</strong>, and you <strong>must</strong> send it to your Regional Center after confirmation of admission along with a copy of your <strong>admission form</strong>. If you don&#39;t send it, the ToC won&#39;t apply.</li></ul><h1 id="dual-enrollment-or-part-admission" tabindex="-1">Dual Enrollment or Part Admission <a class="header-anchor" href="#dual-enrollment-or-part-admission" aria-label="Permalink to &quot;Dual Enrollment or Part Admission&quot;">​</a></h1><p>The NIOS offers a Dual Enrollment or Part Admission scheme designed for students who have already passed their 10th or 12th grade from a recognized board but wish to improve their marks in specific subjects or meet eligibility criteria for certain professional courses. It may also be chosen by students who wish to pursue subjects not available in their schools.</p><p><strong>What is NIOS Dual Enrollment?</strong><br> Under this scheme, students can reappear for up to four subjects of their choice through NIOS&#39;s On-Demand Examination (ODE) system. This allows learners to schedule exams at their convenience throughout the year, providing them with an opportunity to add to their academic records without enrolling in a full-time course.</p><p><strong>Eligibility Criteria</strong><br> Students eligible for Dual Enrollment or Part Admission include:</p><ul><li>Those currently studying in a regular school.</li><li>Individuals who have already passed the Secondary (10th) or Senior Secondary (12th) examination or any higher course from a recognized Board or University.</li></ul><p><strong>Certification Details</strong><br> Upon successfully passing the selected subjects, NIOS issues a marksheet reflecting the improved scores. However, no additional certificates such as a migration certificate, transfer certificate, or provisional certificate are provided under this scheme, as it is not a complete high school diploma.</p><p><strong>Who Should Consider This?</strong><br> The Dual Enrollment option is particularly beneficial for:</p><ul><li>Students aiming to improve their scores in specific subjects to meet the eligibility criteria for competitive exams or entry requirements.</li><li>Learners seeking to fulfill subject requirements for professional courses, such as obtaining Math and Physics credits necessary for aviation programs.</li><li>Learners wishing to pursue subjects that are not available in their schools.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Some universities, like Delhi University, do not accept subjects completed via dual enrollment. For example, if a student has studied humanities through CBSE and completed Mathematics through NIOS, they cannot apply to DU’s Economics program, as all the required subjects need to be in the main high school diploma. So please check your university’s requirements before choosing this path.</p></div><p><strong>Admission Process</strong><br> To apply for Dual Enrollment or Part Admission, students should:</p><ol><li>Visit the NIOS official website.</li><li>Complete the online admission form, selecting the option for Dual Enrollment or Part Admission.</li><li>Stream 3 should be chosen if you are a 10th grader, and Stream 4 if you are in Grade 12. These streams will allow you to take the exams year-round (except for April-May and Oct-Nov), as an On-Demand Student.</li><li>Stream 2 will allow you to take the exam in the Oct-Nov Exam series only.</li><li>Upload the required documents, including previous marksheets and identification proofs.</li><li>Pay the applicable admission fees online.</li></ol>',22)]))}const g=s(i,[["render",n]]);export{p as __pageData,g as default};
